// ── Normalización ───────────────────────────────────────────────────────────

// NormalizeModeration backfills every collection field that decoded as `nil`
// (from a partial Mongo doc or a legacy cache entry) with a non-nil empty
// value, mirroring the zod `.default([])` / `.default({})`. This keeps the JSON
// body emitting `[]` / `{}` instead of `null` — the exact shape the Node
// service produces after re-parsing through `moduleModerationSchema`.
//
// Scalars and nullable pointers are left untouched: a stored `null` stays
// `null`, matching the `string | null` fields (`log_channel_id`, `mute.role_id`,
// each command's `dm_embed.color`, los `alert_*` del v3). Idempotent.
//
// OJO: normalizar NO es migrar. Aquí sólo se rellenan colecciones vacías; los
// defaults NO-cero del v3 (`timeout_ms`, ventanas, umbrales) los pone
// `MigrateModerationRaw`.
func NormalizeModeration(m *ModuleModeration) {
	if m == nil {
		return
	}

	normalizeModerationAccess(&m.CommandsGlobal)

	if m.Commands == nil {
		m.Commands = map[string]ModerationCommand{}
	} else {
		for k, v := range m.Commands {
			normalizeModerationAccess(&v.Access)
			v.Aliases = ensureModerationStrSlice(v.Aliases)
			m.Commands[k] = v
		}

