// UpdateModuleTempvoiceBody mirrors the Node `updateModuleTempVoiceSchema` (a
// `.strict()` object of `.optional()` fields). Unlike the READ schema, the
// PATCH schema excludes only `schema_version` and `updated_at` (server-managed).
// The top-level `name_blacklist`, `panel` and `command_mode` (added in v3/v4/v7)
// ARE patchable — omitting them here made the strict decoder reject them as
// `unrecognized_keys` on any PATCH that included them (e.g. saving the panel from
// the dashboard) → 400. Every field is a pointer so the strict decoder can validate
// the shape; the handler then re-decodes the SAME raw body as `map[string]any`,
// which the repository merges into the existing subdoc via
// `mongo.MergeDeepJSON` by KEY PRESENCE: a key absent in the body is left
// alone; an explicit `false`/`0`/`""`/`null` is applied and overrides the
// stored value; nested objects recurse (so a partial
// `{"defaults":{"bitrate":96000}}` PATCH preserves the other defaults);
// slices (`creators`) replace wholesale; maps merge per-key.
//
// PER OLA-3 NOTE: the greeter/logs/music bodies bind via Fiber's default
// decoder (silently drops unknown keys, parity with Mongoose) — only
// modmail/tempvoice/giveaway/moderation carry the strict unknown-key
// rejection. The nested field types are the full `dbguild.Tempvoice*`
// shapes: every zod PATCH sub-schema matches its parent type
// field-for-field, so no valid key is rejected. Go's json decoder does
// NOT enforce zod's REQUIRED-ness inside a present nested object, so a
// partial command entry that Node would 400 is accepted here and the
// missing leaves stay zero — the same non-strict-required behaviour
// every Go module body has.
type UpdateModuleTempvoiceBody struct {
	Enabled        *bool                                `json:"enabled,omitempty"`
	Creators       *[]dbguild.TempvoiceCreator          `json:"creators,omitempty"`
	NameBlacklist  *[]string                            `json:"name_blacklist,omitempty"`
	Panel          *dbguild.TempvoicePanel              `json:"panel,omitempty"`
