app := fiber.New(fiber.Config{
	AppName: "api-db-go",
	// Fiber's default is 4 MiB, which `/messages/bulk` outgrows: the route
	// accepts 1000 rows and a message with full embeds and ten attachments
	// runs to tens of KB, so a flush of 500 rich messages measured ~18 MiB.
	// The server answered 413, core's buffer retried once and then dropped
	// the whole batch — hundreds of messages lost with only a log line.
	//
	// Two guards, because either alone is not enough: core now also splits
	// flushes by serialized size (`maxBatchBytes`, 3 MiB) so it never builds
	// a body this big in the first place. This limit is the backstop for a
	// client that does not, sized to fit the 1000-row ceiling the validator
	// enforces rather than to be the thing that enforces it.
	BodyLimit: 32 * 1024 * 1024,
	// trustProxy / ProxyHeader mirror Fastify's `trustProxy: true` so
	// `c.IP()` and `c.Protocol()` reflect the real client when the
	// service runs behind Cloudflare / the Rust proxy. The Node side
	// already passes `trustProxy: true`; without this Go's logs
	// would show the proxy's IP for every request.
	ProxyHeader: fiber.HeaderXForwardedFor,
	TrustProxy:  true,
	// Custom global error handler so an uncaught downstream error
	// surfaces as a structured ResultData envelope rather than the
	// Fiber default plain-text 500.
	ErrorHandler: globalErrorHandler,
})

