1	// Package validations holds the request DTOs for the bots-guilds endpoints
2	// and the validator binding. Field shapes mirror the Zod schemas in
3	// `services/api-db/src/domain/zod-schemas/validations/guild-validations.ts`.
4	package validations
5	
6	import (
7		"errors"
8		"strings"
9	
10		"github.com/go-playground/validator/v10"
11	
12		"kena.bot/api-db-go/internal/domain/dbguild"
13	)
14	
15	// Validator wraps a singleton `*validator.Validate`. The struct lets us
16	// register custom tags / translations in one place and keep tests cheap.
17	type Validator struct {
18		v *validator.Validate
19	}
20	
21	// NewValidator builds the singleton with the validator config api-db-go
22	// uses: required tag for non-empty strings, plus the standard struct
23	// validations the handlers depend on.
24	func NewValidator() *Validator {
25		v := validator.New(validator.WithRequiredStructEnabled())
26		return &Validator{v: v}
27	}
28	
29	// Struct runs validation on a request DTO. Returned errors are
30	// `validator.ValidationErrors` so the caller can format them per-field
31	// before responding.
32	func (v *Validator) Struct(s any) error {
33		return v.v.Struct(s)
34	}
35	
36	// ----- Path params -----
37	
38	// BotParams matches `paramsBotValidation` (bot_id only).
39	type BotParams struct {
40		BotID string `params:"bot_id" validate:"required"`
41	}
42	
43	// GuildParams matches `paramsGuildValidation` (bot_id + guild_id).
44	type GuildParams struct {
45		BotID   string `params:"bot_id"   validate:"required"`
46		GuildID string `params:"guild_id" validate:"required"`
47	}
48	
49	// ----- Query strings -----
50	
51	// GuildQuery matches `queryGuildValidation` — the optional `modules` flag
52	// kept as a string because the TS handler compares it against the literal
53	// "true" rather than parsing it as a bool.
54	type GuildQuery struct {
55		Modules string `query:"modules"`
56	}
57	
58	// IncludesModules reproduces the TS expression `query.modules === "true"`.
59	func (q GuildQuery) IncludesModules() bool {
60		return q.Modules == "true"
61	}
62	
63	// GuildArrayQuery matches `queryGuildArrayValidation` — a comma-separated
64	// list of guild ids. Empty values are rejected to mirror Zod's `.nonempty()`.
65	type GuildArrayQuery struct {
66		GuildIDs string `query:"guild_ids" validate:"required"`
67	}
68	
69	// IDs splits and trims the raw query value, mirroring the Zod
70	// `.transform((str) => str.split(",").map((id) => id.trim()))` step.
71	func (q GuildArrayQuery) IDs() []string {
72		parts := strings.Split(q.GuildIDs, ",")
73		out := make([]string, 0, len(parts))
74		for _, p := range parts {
75			t := strings.TrimSpace(p)
76			if t != "" {
77				out = append(out, t)
78			}
79		}
80		return out
81	}
82	
83	// ----- Request bodies -----
84	
85	// CreateGuildBody matches `bodyCreateGuildValidation`. The TS schema also
86	// requires `bot_id` in the body even though the handler reads it from the
87	// path; we keep the same shape so a client that omits it still gets a 400.
88	type CreateGuildBody struct {
89		GuildID string `json:"guild_id" validate:"required"`
90		BotID   string `json:"bot_id"   validate:"required"`
91	}
92	
93	// EnsureConfigBody matches `bodyEnsureConfigValidation`.
94	type EnsureConfigBody struct {
95		Prefix     string `json:"prefix"      validate:"required"`
96		EmbedColor string `json:"embed_color" validate:"required"`
97		Language   string `json:"language"    validate:"required"`
98	}
99	
100	// UpdateGuildBody matches the partial `bodyGuildData`. Every field is a
101	// pointer so the handler can distinguish "absent" from "zero value" — only
102	// non-nil fields are forwarded into the Mongo `$set` payload.
103	type UpdateGuildBody struct {
104		GuildID           *string              `json:"guild_id,omitempty"`
105		BotID             *string              `json:"bot_id,omitempty"`
106		Prefix            *string              `json:"prefix,omitempty"`
107		Language          *string              `json:"language,omitempty"`
108		EmbedColor        *string              `json:"embed_color,omitempty"`
109		EnabledEmbedColor *bool                `json:"enabled_embed_color,omitempty"`
110		Permissions       *dbguild.Permissions `json:"permissions,omitempty"`
111		// Per-command switch of the bot's general commands. Present = REPLACES the
112		// whole map (same semantics as `permissions`), so the dashboard always
113		// submits every command it knows about and a removed key falls back to
114		// "enabled" instead of keeping a stale entry.
115		Commands *map[string]dbguild.GuildCommand `json:"commands,omitempty"`
116		// Profile: subdocumento con la bio del bot para este guild — SÓLO bio.
117		// Avatar/banner ya no viven aquí: Discord expone esos dos al LEER un
118		// miembro (member.avatar/member.banner → hash → URL de SU CDN), así que
119		// Discord es la fuente de verdad y guardar una copia aquí sólo podía
120		// divergir de ella (pasó de verdad: push a Discord ok, persistencia
121		// aquí falla, el dashboard enseña "sin avatar" con Discord diciendo lo
122		// contrario). `bio` es la excepción: Discord acepta el PATCH pero NUNCA
123		// la devuelve al leer un miembro, así que si no la guardamos aquí se
124		// pierde sin forma de recuperarla — ver dbguild.GuildProfile.
125		// Presente = REEMPLAZA el subdocumento entero (mismo criterio que
126		// `permissions` y `commands`): una cadena vacía es "sin bio propia" —
127		// sólo la AUSENCIA del campo en el body dice "no toques `profile`". Un
128		// body con `profile.avatar`/`profile.banner` (cliente viejo, o un
129		// documento leído tal cual y reenviado) no revienta: este endpoint
130		// decodifica con `json.Unmarshal` liso (ver bots_guilds_handler.go
131		// Update, que NO usa DisallowUnknownFields aquí) y esas dos claves se
132		// descartan en silencio.
133		Profile *dbguild.GuildProfile `json:"profile,omitempty"`
134	}
135	
136	// ToSet produces the BSON document fed to `$set`. Returns nil when no
137	// fields were supplied so the repository can short-circuit instead of
138	// issuing a no-op update.
139	func (b UpdateGuildBody) ToSet() map[string]any {
140		out := map[string]any{}
141		if b.GuildID != nil {
142			out["guild_id"] = *b.GuildID
143		}
144		if b.BotID != nil {
145			out["bot_id"] = *b.BotID
146		}
147		if b.Prefix != nil {
148			out["prefix"] = *b.Prefix
149		}
150		if b.Language != nil {
151			out["language"] = *b.Language
152		}
153		if b.EmbedColor != nil {
154			out["embed_color"] = *b.EmbedColor
155		}
156		if b.EnabledEmbedColor != nil {
157			out["enabled_embed_color"] = *b.EnabledEmbedColor
158		}
159		if b.Permissions != nil {
160			// `permissions` presente REEMPLAZA el subdocumento entero (es un `$set`
161			// sobre la clave), así que se escribe campo a campo y lo que el cliente
162			// no mande desaparece. El dashboard siempre manda los tres.
163			perms := map[string]any{
164				"admin_roles": b.Permissions.AdminRoles,
165				"admin_users": b.Permissions.AdminUsers,
166			}
167			// Sólo cuando viene: un cliente antiguo que no conozca el campo no debe
168			// escribir `module_grants: null` en el documento. `[]` explícito sí se
169			// respeta — es «borra todas las reglas».
170			if b.Permissions.ModuleGrants != nil {
171				grants := make([]any, 0, len(b.Permissions.ModuleGrants))
172				for _, g := range b.Permissions.ModuleGrants {
173					// Documento plano, mismo criterio que `commands`: el `$set` no
174					// depende de cómo codifique el struct sus campos.
175					grants = append(grants, map[string]any{
176						"roles":   g.Roles,
177						"users":   g.Users,
178						"modules": g.Modules,
179					})
180				}
181				perms["module_grants"] = grants
182			}
183			out["permissions"] = perms
184		}
185		if b.Commands != nil {
186			// Se reconstruye entrada a entrada en vez de pasar el mapa tipado tal
187			// cual para que el `$set` viaje como un documento plano (mismo criterio
188			// que `permissions`), sin que la codificación del struct decida por
189			// nosotros el orden ni los nombres de los campos.
190			commands := make(map[string]any, len(*b.Commands))
191			for name, cmd := range *b.Commands {
192				commands[name] = map[string]any{"enabled": cmd.Enabled}
193			}
194			out["commands"] = commands
195		}
196		if b.Profile != nil {
197			// Documento plano, mismo criterio que `commands`: el `$set` no
198			// depende de cómo codifique el struct sus campos. REEMPLAZA el
199			// subdocumento `profile` entero — no fusiona — así que este es
200			// también el punto donde un documento viejo con `avatar`/`banner`
201			// sueltos se limpia solo: la próxima vez que alguien escriba
202			// `profile` para este guild, Mongo sustituye el subdocumento
203			// completo por este mapa de una sola clave y las dos claves
204			// muertas desaparecen como efecto colateral — no hace falta un
205			// script de migración aparte (ver dbguild.GuildProfile).
206			out["profile"] = map[string]any{
207				"bio": b.Profile.Bio,
208			}
209		}
210		if len(out) == 0 {
211			return nil
212		}
213		return out
214	}
215	
216	// FormatFieldError turns a single `validator.FieldError` into the kind of
217	// short message the TS Zod-error pipeline produces. Used by handlers to
218	// build the human-facing `message` of a 400 response.
219	func FormatFieldError(fe validator.FieldError) string {
220		switch fe.Tag() {
221		case "required":
222			return fe.Field() + " is required"
223		default:
224			return fe.Field() + " failed " + fe.Tag()
225		}
226	}
227	
228	// CollectValidationErrors flattens the validator result into a list of
229	// `{field, message}` issues, suitable for embedding in CustomError metadata.
230	// Returns nil when the error is not a `validator.ValidationErrors`.
231	func CollectValidationErrors(err error) []map[string]any {
232		var ves validator.ValidationErrors
233		if !errors.As(err, &ves) {
234			return nil
235		}
236		out := make([]map[string]any, 0, len(ves))
237		for _, fe := range ves {
238			out = append(out, map[string]any{
239				"path":    fe.Namespace(),
240				"message": FormatFieldError(fe),
241			})
242		}
243		return out
244	}
