// Package validations holds the request DTOs for the bots-guilds endpoints
// and the validator binding. Field shapes mirror the Zod schemas in
// `services/api-db/src/domain/zod-schemas/validations/guild-validations.ts`.
package validations

import (
	"errors"
	"strings"

	"github.com/go-playground/validator/v10"

	"kena.bot/api-db-go/internal/domain/dbguild"
)

// Validator wraps a singleton `*validator.Validate`. The struct lets us
// register custom tags / translations in one place and keep tests cheap.
type Validator struct {
	v *validator.Validate
}

// NewValidator builds the singleton with the validator config api-db-go
// uses: required tag for non-empty strings, plus the standard struct
// validations the handlers depend on.
func NewValidator() *Validator {
	v := validator.New(validator.WithRequiredStructEnabled())
	return &Validator{v: v}
}

// Struct runs validation on a request DTO. Returned errors are
// `validator.ValidationErrors` so the caller can format them per-field
// before responding.
func (v *Validator) Struct(s any) error {
	return v.v.Struct(s)
}

// ----- Path params -----

// BotParams matches `paramsBotValidation` (bot_id only).
type BotParams struct {
	BotID string `params:"bot_id" validate:"required"`
}

// GuildParams matches `paramsGuildValidation` (bot_id + guild_id).
type GuildParams struct {
	BotID   string `params:"bot_id"   validate:"required"`
	GuildID string `params:"guild_id" validate:"required"`
}

// ----- Query strings -----

// GuildQuery matches `queryGuildValidation` — the optional `modules` flag
// kept as a string because the TS handler compares it against the literal
// "true" rather than parsing it as a bool.
type GuildQuery struct {
	Modules string `query:"modules"`
}

// IncludesModules reproduces the TS expression `query.modules === "true"`.
func (q GuildQuery) IncludesModules() bool {
	return q.Modules == "true"
}

// GuildArrayQuery matches `queryGuildArrayValidation` — a comma-separated
// list of guild ids. Empty values are rejected to mirror Zod's `.nonempty()`.
type GuildArrayQuery struct {
	GuildIDs string `query:"guild_ids" validate:"required"`
}

// IDs splits and trims the raw query value, mirroring the Zod
// `.transform((str) => str.split(",").map((id) => id.trim()))` step.
func (q GuildArrayQuery) IDs() []string {
	parts := strings.Split(q.GuildIDs, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		t := strings.TrimSpace(p)
		if t != "" {
			out = append(out, t)
		}
	}
	return out
}

// ----- Request bodies -----

// CreateGuildBody matches `bodyCreateGuildValidation`. The TS schema also
// requires `bot_id` in the body even though the handler reads it from the
// path; we keep the same shape so a client that omits it still gets a 400.
type CreateGuildBody struct {
	GuildID string `json:"guild_id" validate:"required"`
	BotID   string `json:"bot_id"   validate:"required"`
}

// EnsureConfigBody matches `bodyEnsureConfigValidation`.
type EnsureConfigBody struct {
	Prefix     string `json:"prefix"      validate:"required"`
	EmbedColor string `json:"embed_color" validate:"required"`
	Language   string `json:"language"    validate:"required"`
}

// UpdateGuildBody matches the partial `bodyGuildData`. Every field is a
// pointer so the handler can distinguish "absent" from "zero value" — only
// non-nil fields are forwarded into the Mongo `$set` payload.
type UpdateGuildBody struct {
	GuildID           *string              `json:"guild_id,omitempty"`
	BotID             *string              `json:"bot_id,omitempty"`
	Prefix            *string              `json:"prefix,omitempty"`
	Language          *string              `json:"language,omitempty"`
	EmbedColor        *string              `json:"embed_color,omitempty"`
	EnabledEmbedColor *bool                `json:"enabled_embed_color,omitempty"`
	Permissions       *dbguild.Permissions `json:"permissions,omitempty"`
	// Per-command switch of the bot's general commands. Present = REPLACES the
	// whole map (same semantics as `permissions`), so the dashboard always
	// submits every command it knows about and a removed key falls back to
	// "enabled" instead of keeping a stale entry.
	Commands *map[string]dbguild.GuildCommand `json:"commands,omitempty"`
	// Profile: subdocumento con la bio del bot para este guild — SÓLO bio.
	// Avatar/banner ya no viven aquí: Discord expone esos dos al LEER un
	// miembro (member.avatar/member.banner → hash → URL de SU CDN), así que
	// Discord es la fuente de verdad y guardar una copia aquí sólo podía
	// divergir de ella (pasó de verdad: push a Discord ok, persistencia
	// aquí falla, el dashboard enseña "sin avatar" con Discord diciendo lo
	// contrario). `bio` es la excepción: Discord acepta el PATCH pero NUNCA
	// la devuelve al leer un miembro, así que si no la guardamos aquí se
	// pierde sin forma de recuperarla — ver dbguild.GuildProfile.
	// Presente = REEMPLAZA el subdocumento entero (mismo criterio que
	// `permissions` y `commands`): una cadena vacía es "sin bio propia" —
	// sólo la AUSENCIA del campo en el body dice "no toques `profile`". Un
	// body con `profile.avatar`/`profile.banner` (cliente viejo, o un
	// documento leído tal cual y reenviado) no revienta: este endpoint
	// decodifica con `json.Unmarshal` liso (ver bots_guilds_handler.go
	// Update, que NO usa DisallowUnknownFields aquí) y esas dos claves se
	// descartan en silencio.
	Profile *dbguild.GuildProfile `json:"profile,omitempty"`
}

// ToSet produces the BSON document fed to `$set`. Returns nil when no
// fields were supplied so the repository can short-circuit instead of
// issuing a no-op update.
func (b UpdateGuildBody) ToSet() map[string]any {
	out := map[string]any{}
	if b.GuildID != nil {
		out["guild_id"] = *b.GuildID
	}
	if b.BotID != nil {
		out["bot_id"] = *b.BotID
	}
	if b.Prefix != nil {
		out["prefix"] = *b.Prefix
	}
	if b.Language != nil {
		out["language"] = *b.Language
	}
	if b.EmbedColor != nil {
		out["embed_color"] = *b.EmbedColor
	}
	if b.EnabledEmbedColor != nil {
		out["enabled_embed_color"] = *b.EnabledEmbedColor
	}
	if b.Permissions != nil {
		// `permissions` presente REEMPLAZA el subdocumento entero (es un `$set`
		// sobre la clave), así que se escribe campo a campo y lo que el cliente
		// no mande desaparece. El dashboard siempre manda los tres.
		perms := map[string]any{
			"admin_roles": b.Permissions.AdminRoles,
			"admin_users": b.Permissions.AdminUsers,
		}
		// Sólo cuando viene: un cliente antiguo que no conozca el campo no debe
		// escribir `module_grants: null` en el documento. `[]` explícito sí se
		// respeta — es «borra todas las reglas».
		if b.Permissions.ModuleGrants != nil {
			grants := make([]any, 0, len(b.Permissions.ModuleGrants))
			for _, g := range b.Permissions.ModuleGrants {
				// Documento plano, mismo criterio que `commands`: el `$set` no
				// depende de cómo codifique el struct sus campos.
				grants = append(grants, map[string]any{
					"roles":   g.Roles,
					"users":   g.Users,
					"modules": g.Modules,
				})
			}
			perms["module_grants"] = grants
		}
		out["permissions"] = perms
	}
	if b.Commands != nil {
		// Se reconstruye entrada a entrada en vez de pasar el mapa tipado tal
		// cual para que el `$set` viaje como un documento plano (mismo criterio
		// que `permissions`), sin que la codificación del struct decida por
		// nosotros el orden ni los nombres de los campos.
		commands := make(map[string]any, len(*b.Commands))
		for name, cmd := range *b.Commands {
			commands[name] = map[string]any{"enabled": cmd.Enabled}
		}
		out["commands"] = commands
	}
	if b.Profile != nil {
		// Documento plano, mismo criterio que `commands`: el `$set` no
		// depende de cómo codifique el struct sus campos. REEMPLAZA el
		// subdocumento `profile` entero — no fusiona — así que este es
		// también el punto donde un documento viejo con `avatar`/`banner`
		// sueltos se limpia solo: la próxima vez que alguien escriba
		// `profile` para este guild, Mongo sustituye el subdocumento
		// completo por este mapa de una sola clave y las dos claves
		// muertas desaparecen como efecto colateral — no hace falta un
		// script de migración aparte (ver dbguild.GuildProfile).
		out["profile"] = map[string]any{
			"bio": b.Profile.Bio,
		}
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

// FormatFieldError turns a single `validator.FieldError` into the kind of
// short message the TS Zod-error pipeline produces. Used by handlers to
// build the human-facing `message` of a 400 response.
func FormatFieldError(fe validator.FieldError) string {
	switch fe.Tag() {
	case "required":
		return fe.Field() + " is required"
	default:
		return fe.Field() + " failed " + fe.Tag()
	}
}

// CollectValidationErrors flattens the validator result into a list of
// `{field, message}` issues, suitable for embedding in CustomError metadata.
// Returns nil when the error is not a `validator.ValidationErrors`.
func CollectValidationErrors(err error) []map[string]any {
	var ves validator.ValidationErrors
	if !errors.As(err, &ves) {
		return nil
	}
	out := make([]map[string]any, 0, len(ves))
	for _, fe := range ves {
		out = append(out, map[string]any{
			"path":    fe.Namespace(),
			"message": FormatFieldError(fe),
		})
	}
	return out
}

