// emitting `[]` / `{}` instead of `null` — the exact shape the Node service
// produces after re-parsing through `moduleMusicSchema`. Idempotent.
func NormalizeMusic(m *ModuleMusic) {
	if m == nil {
		return
	}
	m.RecommendedArtists = ensureMusicStrSlice(m.RecommendedArtists)
	m.TextChannels.ChannelsID = ensureMusicStrSlice(m.TextChannels.ChannelsID)
	m.VoiceChannels.ChannelsID = ensureMusicStrSlice(m.VoiceChannels.ChannelsID)
	m.DJ.Roles = ensureMusicStrSlice(m.DJ.Roles)
	m.DJ.Commands = ensureMusicStrSlice(m.DJ.Commands)

	// v7 additive field: docs/cache entries older than v7 decode with the Go
	// zero value ("") — backfill the zod default, mirroring
	// `audio_quality: z.enum(...).default("default")`.
	if m.AudioQuality == "" {
		m.AudioQuality = MusicAudioQualityDefault
	}

	// v8 additive field. A `nil` slice here means the key was absent from the
	// document, so the guild never configured the list and gets the seed; a
	// stored empty array decodes as a non-nil empty slice and is preserved,
	// because "clean nothing" is a valid choice.
	//
	// Esa distinción nil/vacío es la que sostiene el campo entero, y por eso
	// NO se pasa por `ensureMusicStrSlice` como el resto de colecciones: ahí
	// ausente y vacío significan lo mismo y aquí no.
	//
	// Hace falta además de la comprobación de presencia de `MigrateMusicRaw`
	// porque `ModuleMusicRepository.Update` decodifica el resultado del
	// FindOneAndUpdate directamente al struct, sin pasar por la migración: sin
	// esto, un PATCH de cualquier otro campo escribiría la lista vacía en el
	// hash de Redis y envenenaría los cache-hits siguientes.
	if m.AutoDeleteCommands == nil {
		m.AutoDeleteCommands = append([]string(nil), MusicAutoDeleteCommandsDefault...)
	}

	normalizeMusicAccess(&m.CommandsGlobal)

	if m.Commands == nil {
		m.Commands = map[string]MusicCommand{}
	} else {
		for k, v := range m.Commands {
			normalizeMusicAccess(&v.Access)
			m.Commands[k] = v
		}
	}
}

// normalizeMusicAccess backfills the three access-list ID slices of a
// command-access block so each serialises as `[]`, y repone el `mode` cuando
// llega vacío.
//
// `mode` es un enum (`only` | `all_except`) y la cadena vacía no es un valor:
// sale del decode directo de un bloque que NO existe en el documento. El
// dashboard lo pinta como un select en blanco y su zod lo rechaza al guardar,
// así que se repone el default (`all_except []` = sin restricción), igual que
// se hace con `audio_quality`.
func normalizeMusicAccess(a *MusicCommandAccess) {
	normalizeMusicAccessList(&a.Roles)
	normalizeMusicAccessList(&a.Channels)
	normalizeMusicAccessList(&a.Categories)
}

func normalizeMusicAccessList(l *MusicAccessList) {
	if l.Mode == "" {
		l.Mode = MusicAccessAllExcept
	}
	l.IDs = ensureMusicStrSlice(l.IDs)
}

// MusicAccessComplete indica si un bloque de acceso trae los tres ejes con su
// enum poblado. Se usa para decidir si una entrada de CACHÉ es aprovechable:
// un hash escrito antes del fix del PATCH (decode directo de un documento
// pre-v5) trae los tres `mode` en blanco, y la caché es el único camino que no
// pasa por la migración, así que sin esta comprobación se serviría tal cual
// hasta que expirase el TTL (24 h).
func MusicAccessComplete(a MusicCommandAccess) bool {
	return a.Roles.Mode != "" && a.Channels.Mode != "" && a.Categories.Mode != ""
}

func ensureMusicStrSlice(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

// MusicRawSchemaVersion reads the `schema_version` from a raw (lean) Mongo
// `module_music` subdoc, tolerating the int32/int64/int/float64 shapes the bson
// and JSON decoders can produce. Returns 0 when absent — the repo treats a
// zero/empty subdoc as "apply full defaults" (mirrors Node's
// `parseModule(rawModuleData ?? {})`).
func MusicRawSchemaVersion(raw bson.M) int {
	switch v := raw["schema_version"].(type) {
	case int:
		return v
	case int32:
		return int(v)
	case int64:
		return int(v)
	case float64:
		return int(v)
	}
	return 0
}

// MigrateMusicRaw upgrades a raw (lean POJO) `module_music` subdoc to the
// current v7 typed shape, replicating the Node `moduleMusicMigrationSchema`
// preprocess followed by the `moduleMusicSchema` zod defaults:
//
//   - v4 → v5: `blocked_commands: string[]` becomes, for each listed command,
//     `commands[cmd].enabled = false` (the rest of the entry defaults:
//     use_global all-true, access `all_except []` on every axis), merging into
//     any pre-existing `commands` map. `blocked_commands` is dropped. When there
//     is NO `commands` key and NO blocked list, `commands` defaults to the full
//     `MUSIC_COMMANDS` set (every command enabled).
//   - legacy `use_global: boolean` (music's original v5, pre-b4f57ff) expands to
//     the per-axis `{roles, channels, categories}` object per command.
//   - `commands_global` defaults to unrestricted (`all_except []`) when absent.
//   - v7: `audio_quality` absent (every pre-v7 doc) → "default".
//   - stamps `schema_version = 7` (SchemaVersionMusic).
//
// It overlays present raw leaves onto the defaults (never trusting Go's
// zero-value for an absent leaf — a legacy `{enabled:false}` entry still gets
// `use_global` all-true), so the result matches Node's zod-with-defaults
// field-for-field. Idempotent: a doc already in v7 shape round-trips unchanged.
func MigrateMusicRaw(raw bson.M) ModuleMusic {
	var m ModuleMusic
	// Base decode of the STABLE fields (everything except the command-access
	// maps, which need overlay-onto-default semantics and can carry a legacy
	// boolean `use_global` that would not decode into the struct).
	if b, err := bson.Marshal(stripMusicCommandKeys(raw)); err == nil {
		_ = bson.Unmarshal(b, &m)
	}

	m.CommandsGlobal = musicAccessFromRaw(raw["commands_global"])
	m.Commands = musicCommandsFromRaw(raw["commands"], raw["blocked_commands"])
	// v7: `audio_quality` is absent in every pre-v7 doc — stamp the zod
	// default instead of trusting the zero value.
	if m.AudioQuality == "" {
		m.AudioQuality = MusicAudioQualityDefault
	}
	// v8: `auto_delete_commands` needs a PRESENCE check, not a value check.
	// An empty list is a legitimate configuration ("clean nothing"), so the
	// decoded value alone cannot tell "the admin emptied it" from "the field
	// never existed" — the trick used above for `audio_quality` (where `""` is
	// an impossible sentinel) has no equivalent here. Only the raw document
	// knows, so this is the one place the default can be seeded safely.
	if _, ok := raw["auto_delete_commands"]; !ok {
